// 本人文书页只展示实际获知内容；远方的第二份签署不会因同组织或旧任职自动暴露。
#include "treaty_passage_command.hpp"
#include "treaty_passage_detail.hpp"
#include "resident/storage/common_codec.hpp"
namespace hanmo::resident {
namespace {
using V=BoundaryValue;using A=V::Array;using namespace treaty_passage_detail;
struct Known {StableId id;DocumentKnowledge document;Integer information=0;};
// 后收到旧副本不抹去已经亲见的双签；按签署信息层级再按真实文书序选择。
std::map<StableId,Known> known_documents(const Audit& audit,const StableId& actor){std::map<StableId,Known> known;for(const auto& pair:audit.documents){if(!knows(pair.second,actor))continue;Integer information=0;if(!pair.second.signature_id.empty()){auto source=audit.documents.find(pair.second.signature_id);if(source!=audit.documents.end())information=source->second.sequence;}auto old=known.find(pair.second.offer_id);if(old==known.end()||information>old->second.information||(information==old->second.information&&pair.second.sequence>old->second.document.sequence))known[pair.second.offer_id]={pair.first,pair.second,information};}return known;}
StableId provider(const TreatyPassageContext& c,const StableId& actor){StableId result;for(const auto& meeting:c.diplomacy.interaction.interactions){if(meeting.phase!="say"&&meeting.phase!="choice")continue;StableId other;if(meeting.actor_id==actor)other=meeting.context.provider_actor_id;else if(meeting.context.provider_actor_id==actor)other=meeting.actor_id;if(other.empty())continue;if(!result.empty())return {};result=other;}return result;}
std::optional<ActingAuthority> current_authority(const TreatyPassageContext& c,const DiplomaticOffer& offer,const DiplomaticMissionPolicy& policy,const StableId& actor){for(const auto& id:{offer.issuer.office_id,policy.target_office_id}){const auto* office=c.diplomacy.organizations.offices.find(id);if(office&&office->holder_actor_id==std::optional<StableId>{actor})return ActingAuthority{office->organization_id,office->id,office->epoch,actor};}return {};}
V action(const TreatyPassageContext& c,const StableId& actor,const StableId& text,const TreatyPassageCommand& command){auto quote=preview_treaty_passage_command(c,actor,command);return boundary::obj({{"text",V{text}},{"command",V{treaty_passage_command_kind(command)}},{"params",encode_treaty_passage_command(command)},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}}});}
StableId named(const CommonCatalog& catalog,const StableId& key){const auto* text=catalog.texts.find(key);return text?*text:key;}
}
Outcome<V> query_treaty_passage_page(const TreatyPassageContext& c,const CommonCatalog& common,const StableId& observer,Integer cursor){
    if(observer!=c.diplomacy.common.state().metadata.player_actor_id)return {false,{},common_failure("TreatyPassageObserverMismatch").error};auto history=audit(c);if(!history.ok)return {false,{},history.error};auto known=known_documents(history.value,observer);if(cursor<0||cursor>Integer(known.size()))return {false,{},common_failure("InvalidTreatyPassageCursor").error};A rows;const auto other=provider(c,observer);Integer index=0;
    for(const auto& item:known){if(index++<cursor)continue;if(rows.size()==32)break;const auto& document=item.second;const auto* offer=c.diplomacy.state.offers.find(item.first);const auto* terms=offer?c.diplomacy.catalog.passage_terms.find(offer->terms_id):nullptr;const auto* policy=offer?c.diplomacy.catalog.mission_policies.find(offer->policy_id):nullptr;if(!offer||!terms||!policy||!c.catalog.provisions.find(terms->id))continue;
        const auto* signature=document.document.signature_id.empty()?nullptr:c.state.signatures.find(document.document.signature_id);const bool both=signature&&!signature->prior_signature_id.empty();StableId status=both?"ratified":signature?"one_signature":"accepted_pending_signatures";StableId description=both?"双方已明确签署；个人通行仍按当前实际控制与成员资格检查。":signature?"本人已获知一方签署，另一方尚需明确认可。":"已收到真实接受回复；双方尚须各自明确签署。";A actions;
        if(both){if(c.diplomacy.common.tick()>=signature->tick+terms->duration_ticks){status="expired";description="本人持有的双签条约已经届满，不再提供新通行许可。";}else if(c.diplomacy.common.tick()>=signature->tick+terms->duration_ticks-terms->expiry_notice_ticks)description+=" 已进入约定的届满提醒期。";}
        if(!other.empty()){actions.push_back(action(c,observer,"当面交示这份真实文书",TreatyPassagePresentCommand{offer->id,document.document.reply_id,document.id,other,offer->terms_revision}));auto authority=current_authority(c,*offer,*policy,observer);const bool signed_by_me=signature&&signature->authority.organization_id==(authority?authority->organization_id:StableId{});if(authority&&!both&&!signed_by_me)actions.push_back(action(c,observer,"以本人当前公职明确签署",TreatyPassageSignCommand{*authority,offer->id,document.document.reply_id,document.id,signature?signature->id:StableId{},other,offer->terms_revision}));}
        if(!other.empty()&&!both){auto proposals=propose_treaty_passage_npc(c,other);if(!proposals.ok)return {false,{},proposals.error};if(std::any_of(proposals.value.begin(),proposals.value.end(),[&](const auto& cmd){return cmd.offer_id==offer->id;}))actions.push_back(boundary::obj({{"text",V{"等候对方明确认可半日"}},{"command",V{"advance"}},{"params",V{V::Dict{}}},{"available",V{true}},{"code",V{StableId{}}}}));}
        rows.push_back(boundary::obj({{"id",V{offer->id}},{"source_fact_id",V{document.id}},{"display_name",V{named(common,terms->name_key)}},{"text",V{"通行条约："+description}},{"terms_text",V{named(common,terms->name_key)+"。期限"+std::to_string(terms->duration_ticks)+"半日；不授公军、征调或资产处置。"}},{"known_treaty_state",V{status}},{"actions",V{std::move(actions)}}}));
    }
    return {true,boundary::obj({{"ok",V{true}},{"rows",V{std::move(rows)}},{"cursor",V{cursor}},{"next_cursor",V{std::min<Integer>(Integer(known.size()),cursor+32)}},{"truncated",V{cursor+32<Integer(known.size())}}}),{}};
}
Outcome<V> merge_treaty_passage_page(const TreatyPassageContext& c,const CommonCatalog& common,const StableId& observer,V original){auto page=query_treaty_passage_page(c,common,observer);if(!page.ok)return page;auto* rows=original.find("rows");const auto* extra=page.value.find("rows");if(!rows||!rows->as<A>()||!extra||!extra->as<A>())return {false,{},common_failure("InvalidTreatyPassagePage").error};for(const auto& row:*extra->as<A>()){const auto* id=row.find("id");auto found=std::find_if(rows->as<A>()->begin(),rows->as<A>()->end(),[&](const auto& old){return old.find("id")&&id&&compare_boundary(*old.find("id"),*id).exact();});if(found==rows->as<A>()->end())rows->as<A>()->push_back(row);else *found=row;}if(auto* truncated=original.find("truncated")){const auto* old=truncated->as<bool>();const auto* added=page.value.find("truncated")->as<bool>();if(old&&added)truncated->data=*old||*added;}return {true,std::move(original),{}};}
Outcome<std::vector<TreatyPassageSignCommand>> propose_treaty_passage_npc(const TreatyPassageContext& c,const StableId& actor){std::vector<TreatyPassageSignCommand> result;if(actor==c.diplomacy.common.state().metadata.player_actor_id)return {true,std::move(result),{}};auto history=audit(c);if(!history.ok)return {false,{},history.error};const auto other=provider(c,actor);if(other.empty())return {true,std::move(result),{}};for(const auto& item:known_documents(history.value,actor)){const auto* offer=c.diplomacy.state.offers.find(item.first);const auto* policy=offer?c.diplomacy.catalog.mission_policies.find(offer->policy_id):nullptr;const auto* provision=offer?c.catalog.provisions.find(offer->terms_id):nullptr;if(!offer||!policy||!provision)continue;auto authority=current_authority(c,*offer,*policy,actor);if(!authority||std::find(provision->npc_ratifier_office_ids.begin(),provision->npc_ratifier_office_ids.end(),authority->office_id)==provision->npc_ratifier_office_ids.end())continue;const auto* prior=item.second.document.signature_id.empty()?nullptr:c.state.signatures.find(item.second.document.signature_id);if(prior&&(!prior->prior_signature_id.empty()||prior->authority.organization_id==authority->organization_id))continue;TreatyPassageSignCommand command{*authority,offer->id,item.second.document.reply_id,item.second.id,prior?prior->id:StableId{},other,offer->terms_revision};auto preview=preview_treaty_passage_signature(c,actor,command);if(!preview.ok){if(preview.error.kind!=ErrorKind::rule)return {false,{},preview.error};continue;}result.push_back(std::move(command));if(result.size()==16)break;}return {true,std::move(result),{}};}
}
